// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuenta/ficha", wrapper.MiFicha)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuenta/resumen", wrapper.MiResumen)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuenta/pedidos", wrapper.MisPedidos)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuenta/presupuestos", wrapper.MisPresupuestos)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuenta/presupuestos/{numero}", wrapper.MiPresupuesto)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/cuenta/presupuestos/{numero}/respuesta", wrapper.ResponderPresupuesto)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/cuenta/datos", wrapper.GuardarMisDatos)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuenta/direcciones", wrapper.MisDirecciones)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/cuenta/direcciones", wrapper.GuardarDireccion)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/cuenta/direcciones/{id}", wrapper.BorrarDireccion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuenta/pedidos/{numero}", wrapper.MiPedido)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/pedidos/{numero}/seguimiento", wrapper.SeguirPedido)

	return m
}

